/**
 * What ``POST /ingest/file`` returns. ``INGEST_SPEC.md`` 5.7.
 *
 * The spec's response is "the file node id plus the current attempt log". The identity
 * fields alongside it are the ``file`` block of 3.3 — they are what the caller needs to
 * confirm the bytes that landed are the bytes it sent, without a second round trip.
 *
 * 5.7 describes this call as returning BEFORE extraction, with one ``pending`` attempt.
 * That is true once the queue exists (phasing step 4). Today probe runs inline, so the
 * log comes back with probe already terminal. The response shape is the same either
 * way; only the status in it differs, and it is the real one.
 */
export interface FileUploadResponse {
  /**
   * The file node — root of the tree ingestion builds
   */
  document_id: number;
  filename: string;
  usetype: string;
  /**
   * 'in_flight' until structuring finishes (spec 3.1)
   */
  settled: string;
  byte_size: number;
  /**
   * sha256:<hex> of the uploaded bytes
   */
  content_hash: string;
  /**
   * lob:<oid> — the Postgres large object holding them
   */
  blob_ref: string;
  /**
   * What the client said; null if it said nothing
   */
  declared_mime: string | null;
  /**
   * What the bytes are; null if unrecognised
   */
  detected_mime: string | null;
  /**
   * magic_bytes | zip_manifest | content_sniff
   */
  detected_by: string | null;
  /**
   * The node's attempt log as it stands (spec 3.4), newest last
   */
  attempts: Array<AttemptRecord>;
  /**
   * True when these exact bytes were already stored in a `file` node the caller may read, so `document_id` names a node this request FOUND rather than one it created: no second document, no second blob, and nothing enqueued. Named to match `IngestResponse.was_existing`, which reports the same thing for the text pipeline. It is the flag an HTTP layer would key a 200 on instead of the declared 201 — `@expose` declares one status per operation today, so the route still answers 201 and the body is where the distinction lives.
   */
  was_existing?: boolean;
  /**
   * Whether an access-control root sits at or above this node. FALSE means the node is UNPROTECTED — readable and writable by anyone holding a token — which is the documented default, not a fault. It is reported because until now the two states were indistinguishable on the wire: a subtree meant to be governed whose grant was never issued looked exactly like one meant to be open. `GET /access/audit` is the corpus-wide version of the same question.
   */
  governed?: boolean;
  /**
   * The access-control roots at or above this node. Empty when `governed` is false.
   */
  governing_acrs?: Array<number>;
  /**
   * True when the returned node is placed under `parent_id` by a `contains` DocumentLink rather than by parentage — the deduplicated form of 'put this file in that folder'. A link is a GRAPH edge, so the node's `parent_id` is unchanged and a subtree walk of the parent does NOT reach it. False when this request created the node (parentage did the job) and false when the existing node is already a tree child of that parent (the tree edge already says it, and a duplicate graph edge would only add noise).
   */
  linked_into_parent?: boolean;
}

