/**
 * Bind a shape to a scope of documents.
 *
 * Exactly one of the three scope fields is set, and which one is set decides
 * ``scope_type``. They are three named fields rather than one free JSONB object because
 * the set is CLOSED (``models/ontology.py``): each names a different query the resolver
 * runs, and a scope with no query behind it would silently match nothing.
 */
export interface ShapeBindingCreate {
  shape_iri: string;
  /**
   * scope_type 'usetype' — matched against documents.usetype
   */
  usetype_pattern?: string | null;
  /**
   * scope_type 'subtree' — the node and everything below it
   */
  parent_id?: number | null;
  /**
   * scope_type 'documents' — exactly these nodes
   */
  document_ids?: Array<number> | null;
  description?: string | null;
}

/**
 * A stored binding.
 */
export interface ShapeBindingResponse {
  id: number;
  ontology_name: string;
  shape_iri: string;
  scope_type: string;
  scope?: Record<string, unknown>;
  description?: string | null;
  created_at?: string | null;
}

/**
 * One ``sh:property`` constraint, in the subset 5.1 admits.
 *
 * Every field below ``path`` is Optional because SHACL says every one of them is: a
 * property shape may declare a path and nothing else. A field that is null here was
 * ABSENT from the Turtle, and that is a different statement from a constraint with a
 * permissive value — a null ``min_count`` is "unconstrained", ``0`` is "explicitly
 * optional".
 */
export interface ShapeProperty {
  /**
   * sh:path — the predicate IRI this constrains
   */
  path: string;
  /**
   * sh:minCount
   */
  min_count?: number | null;
  /**
   * sh:maxCount
   */
  max_count?: number | null;
  /**
   * sh:datatype, an xsd: IRI
   */
  datatype?: string | null;
  /**
   * sh:class — the class a resource-valued object must be
   */
  class_iri?: string | null;
  /**
   * sh:in, as a list of lexical forms. A closed set — which is what a spreadsheet column with few distinct values becomes (SPRINT_0_3_0.md Part 3 step 1).
   */
  allowed_values?: Array<string> | null;
  /**
   * sh:name, if the shape gave one
   */
  name?: string | null;
  /**
   * sh:description, if given
   */
  description?: string | null;
}

/**
 * One ``sh:NodeShape``, reduced to the subset this appliance reads.
 */
export interface ShapeSummary {
  iri: string;
  /**
   * sh:targetClass. Null means the shape declares no target, so nothing selects it automatically — it can still be bound to a scope explicitly.
   */
  target_class?: string | null;
  properties?: Array<ShapeProperty>;
}

/**
 * Ask for one binding to be run against the data it is bound to.
 *
 * ``docs/SPRINT_0_5_0.md`` Block A step 4. The binding is the whole request: it already
 * names the ontology, the shape and the scope, and a request that re-stated any of them
 * would be free to disagree with the row it names.
 */
export interface ShapeValidationRequest {
  /**
   * The binding to run. It must belong to the ontology in the path — a binding under another vocabulary is a 404 here rather than a run against the wrong shape.
   */
  binding_id: number;
  /**
   * Which layer of the triple store the data graph is built from. 'any' is the live graph as it stands, which is what a validation run normally asks about; 'asserted' is `derived_by IS NULL`, which is what a rule pass reads. Invalidated triples are never included at any layer.
   */
  provenance?: "any" | "asserted" | "derived";
}

/**
 * What ``POST /ontologies/{name}/validate`` enqueued — a task and the node it fills in.
 *
 * The run has NOT happened when this returns. ``report_document_id`` is a document that
 * exists, is in flight, and carries the request; poll it (``GET /documents/{id}``) and read
 * ``structured_content['validation']`` for the report once its task completes. A run that
 * cannot be completed — this install has no ``pyshacl``, the binding was deleted — leaves
 * that node ``settled='failed'`` with the reason in its attempt log, which is more than a
 * refused request would have left behind.
 */
export interface ShapeValidationRunResponse {
  /**
   * The queued `validate:shape` task
   */
  task_id: number;
  /**
   * The node the report will be written to. In flight until the task runs.
   */
  report_document_id: number;
  binding_id: number;
  ontology_name: string;
  shape_iri: string;
  scope_type: string;
  /**
   * Documents the binding's scope resolved to, AFTER the caller's access filter. This is the set the run is pinned to: the worker holds no principal, so the ids are recorded on the task row rather than re-resolved when it runs.
   */
  scope_document_count: number;
  provenance: string;
  /**
   * Whether the report node carries access grants. It carries exactly the grants the scope's documents are governed by, so a report over restricted data is restricted identically; false means the scope is under no access-control root and the report is readable by every token, like the documents it reports on.
   */
  governed: boolean;
  requested_at: string;
  /**
   * The queued task's status — 'pending' when it is created
   */
  status: string;
}

